def get_total_number_of_sequences(m, n):
    # Initialize a 2D list with zeros
    dp = [[0 for x in range(n + 1)] for y in range(m + 1)]

    # Iterate over all possible values of m and n
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # If there's only one position in the sequence
            if j == 1:
                dp[i][j] = i
            else:
                # Calculate the number of sequences ending with i
                dp[i][j] = dp[i - 1][j] + dp[i // 2][j - 1]

    # The answer is the sum of sequences ending with any value from 1 to m
    return sum(dp[i][n] for i in range(1, m + 1))
