def find_kth(arr1, arr2, k):
    # If arr1 is empty, return the k-th element of arr2
    if len(arr1) == 0:
        return arr2[k - 1]
    # If arr2 is empty, return the k-th element of arr1
    if len(arr2) == 0:
        return arr1[k - 1]
    # If k is 1, return the minimum of the first elements of both arrays
    if k == 1:
        return min(arr1[0], arr2[0])

    # Determine which array has the smaller k/2-th element
    mid1 = float('inf') if len(arr1) < k // 2 else arr1[k // 2 - 1]
    mid2 = float('inf') if len(arr2) < k // 2 else arr2[k // 2 - 1]

    # If the middle element of arr1 is smaller, discard the first half of arr1
    if mid1 < mid2:
        return find_kth(arr1[k // 2:], arr2, k - k // 2)
    else:
        # Otherwise, discard the first half of arr2
        return find_kth(arr1, arr2[k // 2:], k - k // 2)

